"""Direct constrained constructor for 26 nonoverlapping circles."""
import numpy as np
from scipy.optimize import minimize


def construct_packing():
    n = 26
    rows = (5, 6, 5, 6, 4)
    rng = np.random.default_rng(26026)

    def seed(j):
        ys = np.array([.105, .302, .500, .698, .895], float)
        ys += rng.normal(0, .0035, 5)
        out = []
        for k, m in enumerate(rows):
            lo, hi = ((.08, .92) if m == 6 else
                      (.095, .905) if m == 5 else (.185, .815))
            x = np.linspace(lo, hi, m)
            if k & 1:
                x += .5 * (x[1] - x[0])
            x += rng.normal(0, .0025, m)
            out.extend(zip(x, np.full(m, ys[k])))
        return np.asarray(out, float)

    def feasible_radii(p):
        d = np.sqrt(np.maximum(((p[:, None]-p[None, :])**2).sum(2), 1e-30))
        np.fill_diagonal(d, np.inf)
        b = np.minimum.reduce((p[:, 0], p[:, 1], 1-p[:, 0], 1-p[:, 1]))
        r = np.minimum(b, .03)
        for _ in range(35):
            for i in range(n):
                r[i] = max(1e-10, min(b[i], np.min(d[i] - r)))
        return np.maximum(r * (1 - 2e-6), 1e-9)

    def unpack(z):
        return z[:2*n].reshape(n, 2), z[2*n:]

    def cons(z):
        p, r = unpack(z)
        d = np.sqrt(np.maximum(((p[:, None]-p[None,:])**2).sum(2), 1e-30))
        ii, jj = np.triu_indices(n, 1)
        return np.r_[p[:,0]-r, p[:,1]-r, 1-p[:,0]-r, 1-p[:,1]-r,
                     d[ii,jj]-r[ii]-r[jj]-2e-8]

    best = None
    bestv = -np.inf
    for s in range(2):
        p = seed(s)
        r = feasible_radii(p)
        z0 = np.r_[p.ravel(), r]
        res = minimize(lambda z: -np.sum(z[2*n:]), z0, method="SLSQP",
                       bounds=[(0.015, .985)]*(2*n)+[(1e-9, .25)]*n,
                       constraints={"type": "ineq", "fun": cons},
                       options={"maxiter": 360, "ftol": 2e-9, "disp": False})
        z = res.x if np.all(np.isfinite(res.x)) else z0
        p, r = unpack(z)
        # Explicit final repair, independent of optimizer status.
        p = np.clip(p, 1e-8, 1-1e-8)
        r = np.minimum(r, np.minimum.reduce((p[:,0], p[:,1], 1-p[:,0], 1-p[:,1])))
        d = np.sqrt(np.maximum(((p[:,None]-p[None,:])**2).sum(2), 1e-30))
        for _ in range(4):
            for i in range(n):
                for j in range(i+1, n):
                    e = r[i] + r[j] + 2e-9 - d[i,j]
                    if e > 0:
                        if r[i] >= r[j]:
                            r[i] = max(1e-10, r[i]-e)
                        else:
                            r[j] = max(1e-10, r[j]-e)
        r *= 1 - 1e-8
        val = float(r.sum())
        if val > bestv and np.all(np.isfinite(r)):
            bestv, best = val, (p.copy(), r.copy())

    if best is None:
        p = seed(0)
        r = feasible_radii(p)
        return p, r, float(r.sum())
    return best[0], best[1], bestv


def compute_max_radii(centers):
    n = centers.shape[0]
    r = np.minimum.reduce((centers[:,0], centers[:,1],
                           1-centers[:,0], 1-centers[:,1]))
    d = np.sqrt(np.maximum(((centers[:,None]-centers[None,:])**2).sum(2), 1e-30))
    np.fill_diagonal(d, np.inf)
    for i in range(n):
        for j in range(i+1, n):
            if r[i] + r[j] > d[i,j]:
                q = d[i,j] / (r[i]+r[j])
                r[i] *= q
                r[j] *= q
    return r


def run_packing():
    return construct_packing()


def visualize(centers, radii):
    import matplotlib.pyplot as plt
    from matplotlib.patches import Circle
    fig, ax = plt.subplots(figsize=(8, 8))
    ax.set_xlim(0,1); ax.set_ylim(0,1); ax.set_aspect("equal"); ax.grid(True)
    for i, (c, r) in enumerate(zip(centers, radii)):
        ax.add_patch(Circle(c, r, alpha=.5))
        ax.text(c[0], c[1], str(i), ha="center", va="center")
    plt.show()


if __name__ == "__main__":
    c, r, s = run_packing()
    print("Sum of radii:", s)

